h,w=19,16
G=[[4]*w for _ in range(h)]
seeds={1:[(2,2),(4,14),(10,10),(17,9)],6:[(4,4),(6,6),(7,14),(15,2)]}
for col,pts in seeds.items():
 for r,c in pts:G[r][c]=col
# connect 1 aligned (2,2) and (10,10)
for k in range(9):
 r,c=2+k,2+k
 if G[r][c]==4:G[r][c]=1
# 6 rays both diagonals
for r,c in seeds[6]:
 for dr,dc in [(1,1),(1,-1)]:
  for sign in [-1,1]:
   rr,cc=r,c
   while 0<=rr<h and 0<=cc<w:
    if G[rr][cc]==4:G[rr][cc]=6
    rr+=sign*dr;cc+=sign*dc
print('\n'.join(' '.join(map(str,row)) for row in G))
